parameters.jsCode:
// The check itself can take minutes the first time. Waiting for it here would
// hold up the next poll, which would read /check again and run it twice. So
// this answers straight away and the collection workflow sends the result.
const m = $('Read messages').item.json;
return { json: { chat_id: m.chat_id, next_offset: m.next_offset,
  reply: 'Checking all sources now. I will send you what I find when it is done.' } };

const m = $('Read messages').item.json;
const r = $json;
const times = (r.times || '').split(' ').filter(Boolean);
let reply;
if (r.invalid) {
  // the examples use the command they typed, /schedule or /reschedule
  const cmd = `/${m.command}`;
  reply = `I did not understand that. Examples:\n${cmd} 8:00\n${cmd} 8:00 14:00\n${cmd} off`;
} else if (r.times === 'off' || !times.length) {
  reply = 'Automatic checking is off. I check only when you send /check.\n\nTo turn it on: /schedule 8:00';
} else {
  const when = times.length === 1 ? times[0] : times.slice(0, -1).join(', ') + ' and ' + times[times.length - 1];
  reply = `${r.changed ? 'Done. ' : ''}I check the sources every day at ${when} (Finnish time).`
        + '\n\nChange it with /reschedule 8:00 14:00, stop it with /schedule off, or check now with /check.';
}
return { json: { chat_id: m.chat_id, next_offset: m.next_offset, reply } };

// The dashboard owns accounts and says what to answer: a message, with a
// button that opens a link when Telegram can take one. When it cannot be
// reached the editor still hears something, rather than nothing.
const m = $('Read messages').item.json;
const fallback = 'The dashboard is not answering, so I cannot do that right now. Try again in a minute.';
const messages = Array.isArray($json.messages) && $json.messages.length
  ? $json.messages
  : [{ text: typeof $json.reply === 'string' && $json.reply ? $json.reply : fallback }];
return { json: {
  chat_id: m.chat_id,
  next_offset: m.next_offset,
  reply: messages.map((x) => x.text).join('\n\n'),
  messages,
} };
